import{z as n,x as l,o,c as C,q as B,j as t,D as e,d as E,s as r,S as A,b as s}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"SYN cookies","description":"","frontmatter":{"title":"SYN cookies","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/syn-cookies.md","filePath":"cs/syn-cookies.md","lastUpdated":1791063341000}'),c={name:"cs/syn-cookies.md"};function p(d,a,S,k,D,h){const i=l("Mermaid");return o(),C("div",null,[a[2]||(a[2]=B('<h1 id="syn-cookies" tabindex="-1">SYN cookies <a class="header-anchor" href="#syn-cookies" aria-label="Permalink to &quot;SYN cookies&quot;">​</a></h1><div class="epigraph"><p>不把半开连接存进队列，而把状态编码进 SYN-ACK 的序号；ACK 回来再重建。抗泛洪，但可能丢掉选项。</p><footer>—— 据 Bernstein 的 SYN cookies 笔记；RFC 4987 TCP SYN Flooding 整理</footer></div><p><a href="/cs/tcp-state-machine">上一课</a> 的 SYN-RECEIVED 要占 TCB。<a href="/cs/tcp-handshake">握手</a> 假定队列够。缺口是 <strong>SYN flood</strong>：伪造源填满半开。cookies 用密码学或哈希把 MSS 等塞进 seq。本课不把 keepalive 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>攻击者发大量 SYN，源不可达，队列满则合法 SYN 被拒——可用性。Cookie：SYN-ACK 的初始序号 = 哈希(密钥, 四元组, 时间, MSS 编码)，不存 TCB。最终 ACK 校验哈希再创建 ESTABLISHED。代价：时间戳/SACK/缩放可能无法从 32 位里恢复，长肥管道受害者。只在队列压力下启用是常见政策。</p><p>不要把 cookie 写成 TLS cookie 或 QUIC retry 的拷贝，对象类似、编码不同。</p><p><span class="marginnote">TCB（传输控制块）是内核为每条 TCP 连接保存的全部状态：序号、窗口、定时器。半开连接也要占一个 TCB——SYN flood 的本质就是用几十字节的假包骗走几百字节的内核内存。</span></p><p><span class="marginnote">RFC 4987 描述攻击与对策。Linux 实现细节不背。密钥要轮换。</span></p><h3 id="半开搬进序号" tabindex="-1">半开搬进序号 <a class="header-anchor" href="#半开搬进序号" aria-label="Permalink to &quot;半开搬进序号&quot;">​</a></h3><p>抗泛洪，可能丢掉缩放等选项。任播要同一密钥验证。压力下启用是常见政策，永久开启要接受降级。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：存 TCB vs 编码进序号。画：SYN → cookie SYN-ACK → ACK 验证 → 建连。与 RPKI 对照：都是用密码学/哈希抗伪造，一层在路由，一层在传输。</p>',12)),(o(),t(A,null,{default:e(()=>[r(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYN%5B%22SYN%20%E4%B8%8D%E5%AD%98%E8%A1%A8%22%5D%20--%3E%20CK%5B%22%E5%BA%8F%E5%8F%B7%3Dcookie%22%5D%0A%20%20CK%20--%3E%20ACK%5B%22%E5%9B%9E%20ACK%22%5D%0A%20%20ACK%20--%3E%20VER%5B%22%E9%AA%8C%E8%AF%81%E5%90%8E%E5%BB%BA%20TCB%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[E("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"AIMD 尚未开始，cookies 在握手。MSS 钳制仍可发生在 SYN 上。Anycast 与 ECMP：ACK 必须回到能验证同一密钥的实例，否则失败——接住拓扑课。卫星长 RTT 使 cookie 时间窗要宽容。",-1)),(o(),t(A,null,{default:e(()=>[r(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22SYN%20%E5%88%B0%E8%BE%BE%E4%B8%94%E9%98%9F%E5%88%97%E5%8E%8B%E5%8A%9B%E5%A4%A7%22%5D%20--%3E%20C%5B%22%E7%8E%B0%E7%AE%97%20cookie%EF%BC%9A%E5%93%88%E5%B8%8C(%E5%AF%86%E9%92%A5%2C%20%E5%9B%9B%E5%85%83%E7%BB%84%2C%20%E5%88%86%E9%92%9F%E8%AE%A1%E6%95%B0%2C%20MSS)%22%5D%0A%20%20C%20--%3E%20A%5B%22SYN-ACK%20%E6%90%BA%E5%B8%A6%20cookie%20%E4%BD%9C%E5%88%9D%E5%A7%8B%E5%BA%8F%E5%8F%B7%22%5D%0A%20%20A%20--%3E%20R%5B%22ACK%20%E5%9B%9E%E6%9D%A5%EF%BC%9A%E9%87%8D%E7%AE%97%E5%93%88%E5%B8%8C%E6%AF%94%E5%AF%B9%22%5D%0A%20%20R%20--%3E%7C%22%E5%8C%B9%E9%85%8D%E4%B8%94%E5%9C%A8%E6%97%B6%E9%97%B4%E7%AA%97%E5%86%85%22%7C%20E%5B%22%E6%AD%A4%E5%88%BB%E6%89%8D%E5%BB%BA%20TCB%EF%BC%8C%E8%BF%9B%E5%85%A5%20ESTABLISHED%22%5D%0A%20%20R%20--%3E%7C%22%E4%B8%8D%E5%8C%B9%E9%85%8D%E6%88%96%E5%B7%B2%E8%BF%87%E6%9C%9F%22%7C%20D%5B%22%E9%9D%99%E9%BB%98%E4%B8%A2%E5%BC%83%EF%BC%8C%E9%9B%B6%E5%86%85%E5%AD%98%E5%8D%A0%E7%94%A8%22%5D%0A%20%20FAKE%5B%22%E4%BC%AA%E9%80%A0%E6%BA%90%E6%B0%B8%E4%B8%8D%E5%9B%9E%20ACK%22%5D%20--%3E%20NOPE%5B%22%E6%B2%A1%E6%9C%89%E4%BB%BB%E4%BD%95%20TCB%20%E7%94%9F%E6%88%90%EF%BC%9A%E9%98%9F%E5%88%97%E4%B8%8D%E6%B6%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">数字实例：cookie 里编入「分钟计数」，服务器只接受当前与上一分钟生成的 cookie。若不编码时间，攻击者可以攒一万个旧 cookie 慢慢回放；有了时间窗，过期即作废，重放失去意义。</span></p><p>合法瞬时高峰也会触发 cookies，表现为偶发无窗口缩放。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SYNPROXY 的全部。保活与半开是下一课。后课默认：压力下用 cookie 抗泛洪；选项可能丢。</p><p>把 cookies 当默认永久开启要接受功能降级。</p><p><span class="marginnote">常见误区：以为开了 cookie 就万事大吉。32 位序号塞不下 MSS 之外的 SACK、窗口缩放等选项，长肥管道（大带宽高时延链路）会因此跑不满——这是「可用性换功能」的定价，不是 bug。</span></p><p>下一课<a href="/cs/keepalive-half-open">保活与半开</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>半开状态搬进 SYN-ACK 序号。</li><li>抗 SYN 泛洪，可能丢 TCP 选项。</li><li>验证要密钥与时间窗，任播要同源。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 4987；Bernstein cookies。</li></ul>',9))])}const N=n(c,[["render",p]]);export{T as __pageData,N as default};
